/* The word primitives with no one-expression C form: a carry chain's step, in
   both directions, and the division of a two-word number by a word. Each takes
   the builtin a C compiler offers -- gcc and clang lower these to adc, sbb and
   div -- and otherwise a portable form, which is what tcc runs. Defining
   Z_WORD_PORTABLE (-DZ_WORD_PORTABLE) takes the portable forms under any
   compiler, which is how make bench-math sets the two tiers side by side. */
#if defined(__has_builtin) && !defined(Z_WORD_PORTABLE)
#if __has_builtin(__builtin_addcll) && __has_builtin(__builtin_subcll)
#define Z_WORD_CARRY_BUILTINS 1
#endif
#endif

/* a + b + cin, and the carry out of it in *cout. cin is 0 or 1. */
static inline uint64_t z_word_addc(uint64_t a, uint64_t b, uint64_t cin, uint64_t* cout) {
#if defined(Z_WORD_CARRY_BUILTINS)
    unsigned long long c;
    uint64_t s = __builtin_addcll(a, b, cin, &c);
    *cout = c;
    return s;
#else
    uint64_t s = a + b;
    uint64_t r = s + cin;
    *cout = (uint64_t)(s < a) | (uint64_t)(r < s);
    return r;
#endif
}

/* a - b - bin, and the borrow out of it in *bout. bin is 0 or 1. */
static inline uint64_t z_word_subb(uint64_t a, uint64_t b, uint64_t bin, uint64_t* bout) {
#if defined(Z_WORD_CARRY_BUILTINS)
    unsigned long long c;
    uint64_t d = __builtin_subcll(a, b, bin, &c);
    *bout = c;
    return d;
#else
    uint64_t d = a - b;
    uint64_t r = d - bin;
    *bout = (uint64_t)(a < b) | (uint64_t)(d < bin);
    return r;
#endif
}

/* (hi, lo) / d, the remainder in *rem. The quotient fits a word only when
   hi < d, and a zero d has none: both panic. The portable form is long
   division in 32-bit digits: d is shifted until its top bit is set, so each
   estimate of a quotient digit from the top digits is at most two too large,
   and each correction step lowers it by one. */
static uint64_t z_word_divwide(uint64_t hi, uint64_t lo, uint64_t d, uint64_t* rem) {
    if (d == 0) z_panic("divWide: division by zero");
    if (hi >= d) z_panic("divWide: the quotient does not fit a word (hi >= by)");
#if defined(__SIZEOF_INT128__) && !defined(Z_WORD_PORTABLE)
    unsigned __int128 n = ((unsigned __int128)hi << 64) | lo;
    *rem = (uint64_t)(n % d);
    return (uint64_t)(n / d);
#else
    const uint64_t b = 4294967296u;
    int s = __builtin_clzll(d);
    uint64_t v = d << s;
    uint64_t vn1 = v >> 32;
    uint64_t vn0 = v & 0xFFFFFFFFu;
    uint64_t un32 = s == 0 ? hi : (hi << s) | (lo >> (64 - s));
    uint64_t un10 = lo << s;
    uint64_t un1 = un10 >> 32;
    uint64_t un0 = un10 & 0xFFFFFFFFu;
    uint64_t q1 = un32 / vn1;
    uint64_t rhat = un32 - q1 * vn1;
    while (q1 >= b || q1 * vn0 > b * rhat + un1) {
        q1 -= 1;
        rhat += vn1;
        if (rhat >= b) break;
    }
    uint64_t un21 = un32 * b + un1 - q1 * v;
    uint64_t q0 = un21 / vn1;
    rhat = un21 - q0 * vn1;
    while (q0 >= b || q0 * vn0 > b * rhat + un0) {
        q0 -= 1;
        rhat += vn1;
        if (rhat >= b) break;
    }
    *rem = (un21 * b + un0 - q0 * v) >> s;
    return q1 * b + q0;
#endif
}
static char* z_sv_to_cstr(z_t82_t v) {
    char* buf = (char*)z_xmalloc(v.size + 1);
    if (v.size > 0) memcpy(buf, v.data, v.size);
    buf[v.size] = '\0';
    return buf;
}

static z_t779_t z_io_errno_to_IoError(int e) {
    z_t779_t r = {0};
    r.data = NULL;
    switch (e) {
        case ENOENT:  r.tag = Z_T779_TAG_0; break;
        case EACCES:
        case EPERM:   r.tag = Z_T779_TAG_1; break;
        case EINTR:   r.tag = Z_T779_TAG_2; break;
        case EEXIST:  r.tag = Z_T779_TAG_6; break;
        case EISDIR:  r.tag = Z_T779_TAG_7; break;
        case ENOTDIR: r.tag = Z_T779_TAG_8; break;
        case ENOSPC:  r.tag = Z_T779_TAG_9; break;
        default:      r.tag = Z_T779_TAG_10; break;
    }
    return r;
}


/* shared helper: write all bytes; returns 0 ok, errno on failure. */
static int z_io_write_all(int fd, const char* data, uint64_t size) {
    uint64_t off = 0;
    while (off < size) {
        long n = write(fd, data + off, size - off);
        if (n < 0) {
            if (errno == EINTR) continue;
            return errno;
        }
        off += (uint64_t)n;
    }
    return 0;
}

/* shared helper: path + open flags -> write content -> close.
   path and content are borrowed views; caller retains. */
static z_t4341_t z_io_write_common(
    z_t82_t path, z_t82_t content, int flags
) {
    z_t4341_t result = {0};
    char* path_cstr = z_sv_to_cstr(path);
    int fd = open(path_cstr, flags, 0644);
    free(path_cstr);
    if (fd < 0) {
        int e = errno;
        z_t779_t* boxed = (z_t779_t*)z_xmalloc(sizeof(z_t779_t));
        *boxed = z_io_errno_to_IoError(e);
        result.tag = Z_T4341_TAG_0;
        result.data = boxed;
        return result;
    }
    int werr = z_io_write_all(fd, content.data, content.size);
    close(fd);
    if (werr != 0) {
        z_t779_t* boxed = (z_t779_t*)z_xmalloc(sizeof(z_t779_t));
        *boxed = z_io_errno_to_IoError(werr);
        result.tag = Z_T4341_TAG_0;
        result.data = boxed;
        return result;
    }
    result.tag = Z_T4341_TAG_1;
    result.data = NULL;
    return result;
}


static z_t4332_t z_io_u64_ok(uint64_t v);
static z_t4332_t z_io_u64_ok(uint64_t v) {
    z_t4332_t result = {0};
    result.tag = Z_T4332_TAG_1;
    result.i1 = v;
    return result;
}

static z_t4332_t z_io_u64_err(int saved_errno);
static z_t4332_t z_io_u64_err(int saved_errno) {
    z_t4332_t result = {0};
    z_t779_t* boxed = (z_t779_t*)z_xmalloc(sizeof(z_t779_t));
    *boxed = z_io_errno_to_IoError(saved_errno);
    result.tag = Z_T4332_TAG_0;
    result.data = boxed;
    return result;
}


static z_t4341_t z_io_wrap_null_Result(int rc, int saved_errno) {
    z_t4341_t result = {0};
    if (rc == 0) {
        result.tag = Z_T4341_TAG_1;
        result.data = NULL;
        return result;
    }
    z_t779_t* boxed = (z_t779_t*)z_xmalloc(sizeof(z_t779_t));
    *boxed = z_io_errno_to_IoError(saved_errno);
    result.tag = Z_T4341_TAG_0;
    result.data = boxed;
    return result;
}


/* Populate fs from a struct stat. Shared by z_io_stat / z_io_lstat —
   the only behavioral split between them lives in the syscall call
   site (stat(2) follows symlinks, lstat(2) does not). */
static void z_io_fill_filestat(z_t4641_t* fs, const struct stat* sb);
static void z_io_fill_filestat(z_t4641_t* fs, const struct stat* sb) {
    if (S_ISREG(sb->st_mode))       fs->f0 = Z_T4397_TAG_0;
    else if (S_ISDIR(sb->st_mode))  fs->f0 = Z_T4397_TAG_1;
    else if (S_ISLNK(sb->st_mode))  fs->f0 = Z_T4397_TAG_2;
    else                            fs->f0 = Z_T4397_TAG_3;
    fs->f1 = (uint64_t)sb->st_size;
    fs->f2 = (uint64_t)sb->st_mtime;
    fs->f3 = (uint64_t)sb->st_atime;
    fs->f4 = (uint64_t)sb->st_ctime;
    fs->f5 = (uint32_t)sb->st_mode;
    fs->f6 = (uint64_t)sb->st_dev;
    fs->f7 = (uint64_t)sb->st_ino;
    fs->f8 = (uint64_t)sb->st_nlink;
}


static void z_io_eprintln(z_t82_t sv) {
    fprintf(stderr, "%.*s\n", (int)sv.size, sv.data);
}


static bool z_io_exists(z_t82_t path) {
    char* path_cstr = z_sv_to_cstr(path);
    int r = access(path_cstr, F_OK);
    free(path_cstr);
    return r == 0;
}


/* Enumerate directory entries via opendir/readdir/closedir.
   Returns bare entry names (not full paths), skipping `.` and
   `..`, in filesystem order. The list is constructed on stack and
   then boxed heap-side so the result union's void* data can
   carry it; the compiler-generated result destructor calls
   z_t503_destroy on the ok payload, which in turn frees
   each entry's z_t62_t. */
static z_t4614_t z_io_listDir(z_t82_t path);
static z_t4614_t z_io_listDir(z_t82_t path) {
    z_t4614_t result = {0};
    char* path_cstr = z_sv_to_cstr(path);
    DIR* d = opendir(path_cstr);
    int e = errno;
    free(path_cstr);
    if (!d) {
        z_t779_t* boxed = (z_t779_t*)z_xmalloc(sizeof(z_t779_t));
        *boxed = z_io_errno_to_IoError(e);
        result.tag = Z_T4614_TAG_0;
        result.data = boxed;
        return result;
    }
    z_t503_t list = z_t503_create((uint64_t)0);
    struct dirent* entry;
    errno = 0;
    while ((entry = readdir(d)) != NULL) {
        const char* name = entry->d_name;
        if (name[0] == '.' && (name[1] == '\0' ||
            (name[1] == '.' && name[2] == '\0'))) continue;
        z_t503_append(&list, z_t62_new(name));
    }
    closedir(d);
    z_t503_t* boxed = (z_t503_t*)z_xmalloc(sizeof(z_t503_t));
    *boxed = list;
    result.tag = Z_T4614_TAG_1;
    result.data = boxed;
    return result;
}


static z_t4341_t z_io_mkdir(z_t82_t path) {
    char* path_cstr = z_sv_to_cstr(path);
    int rc = mkdir(path_cstr, 0755);
    int e = errno;
    free(path_cstr);
    return z_io_wrap_null_Result(rc, e);
}


/* mkdir -p path. Walks components, creating each missing
   directory with mode 0755. Succeeds if the final path already
   exists as a directory; fails with ioerror if any component
   exists as a non-directory. Allocates a mutable copy of path
   so it can null-terminate prefixes in place. */
static z_t4341_t z_io_mkdirp(z_t82_t path);
static z_t4341_t z_io_mkdirp(z_t82_t path) {
    uint64_t n = path.size;
    char* buf = (char*)z_xmalloc(n + 1);
    if (n > 0) memcpy(buf, path.data, n);
    buf[n] = '\0';
    /* walk, splitting at '/' boundaries */
    for (uint64_t i = 1; i <= n; i++) {
        if (i == n || buf[i] == '/') {
            char saved = buf[i];
            buf[i] = '\0';
            if (buf[0] != '\0') {
                int rc = mkdir(buf, 0755);
                if (rc != 0 && errno != EEXIST) {
                    int e = errno;
                    free(buf);
                    return z_io_wrap_null_Result(-1, e);
                }
            }
            buf[i] = saved;
        }
    }
    free(buf);
    return z_io_wrap_null_Result(0, 0);
}


static z_t781_t z_io_readText(z_t82_t path) {
    /* path is a borrowed view; caller retains ownership */
    z_t781_t result = {0};
    char* path_cstr = z_sv_to_cstr(path);
    int fd = open(path_cstr, O_RDONLY);
    free(path_cstr);
    if (fd < 0) {
        int e = errno;
        z_t779_t* boxed = (z_t779_t*)z_xmalloc(sizeof(z_t779_t));
        *boxed = z_io_errno_to_IoError(e);
        result.tag = Z_T781_TAG_0;
        result.data = boxed;
        return result;
    }
    z_t62_t content = z_t62_create((uint64_t)4096);
    char buf[4096];
    for (;;) {
        long n = read(fd, buf, sizeof(buf));
        if (n == 0) break;
        if (n < 0) {
            if (errno == EINTR) continue;
            int e = errno;
            close(fd);
            z_t62_free(&content);
            z_t779_t* boxed = (z_t779_t*)z_xmalloc(sizeof(z_t779_t));
            *boxed = z_io_errno_to_IoError(e);
            result.tag = Z_T781_TAG_0;
            result.data = boxed;
            return result;
        }
        z_t62_append(&content, buf, (uint64_t)n);
    }
    close(fd);
    z_t62_t* boxed = (z_t62_t*)z_xmalloc(sizeof(z_t62_t));
    *boxed = content;
    result.tag = Z_T781_TAG_1;
    result.data = boxed;
    return result;
}


/* readlink — follow-free read of a symlink's target. readlink(2)
   does not NUL-terminate, and we don't know the exact target size
   up front; loop with a growing buffer until the kernel says the
   full target fit. EINVAL from readlink means the path exists but
   isn't a symbolic link -- surfaced as invalidpath with a
   caller-readable message. The success path breaks out so the body ends
   in its return -- c2mir miscompiles a struct return otherwise. */
static z_t781_t z_io_readlink(z_t82_t path);
static z_t781_t z_io_readlink(z_t82_t path) {
    z_t781_t result = {0};
    char* path_cstr = z_sv_to_cstr(path);
    uint64_t cap = (uint64_t)256;
    char* buf = (char*)z_xmalloc(cap);
    ssize_t n;
    for (;;) {
        n = readlink(path_cstr, buf, cap);
        if (n < 0) {
            int e = errno;
            free(buf);
            free(path_cstr);
            z_t779_t* boxed = (z_t779_t*)z_xmalloc(sizeof(z_t779_t));
            if (e == EINVAL) {
                z_t779_t v = {0};
                v.tag = Z_T779_TAG_3;
                z_t62_t* sp = (z_t62_t*)z_xmalloc(sizeof(z_t62_t));
                *sp = z_t62_new("not a symbolic link");
                v.data = sp;
                *boxed = v;
            } else {
                *boxed = z_io_errno_to_IoError(e);
            }
            result.tag = Z_T781_TAG_0;
            result.data = boxed;
            return result;
        }
        if ((uint64_t)n < cap) break;
        cap *= 2;
        buf = (char*)z_xrealloc(buf, cap);
    }
    z_t62_t target = {0};
    target.size = (uint64_t)n;
    target.capacity = target.size + 1;
    target.data = (char*)z_xmalloc(target.capacity + 1);
    memcpy(target.data, buf, target.size);
    target.data[target.size] = '\0';
    free(buf);
    free(path_cstr);
    z_t62_t* boxed = (z_t62_t*)z_xmalloc(sizeof(z_t62_t));
    *boxed = target;
    result.tag = Z_T781_TAG_1;
    result.data = boxed;
    return result;
}


static z_t4341_t z_io_remove(z_t82_t path) {
    char* path_cstr = z_sv_to_cstr(path);
    /* try unlink first; if EISDIR, fall back to rmdir */
    int rc = unlink(path_cstr);
    int e = errno;
    if (rc != 0 && e == EISDIR) {
        rc = rmdir(path_cstr);
        e = errno;
    }
    free(path_cstr);
    return z_io_wrap_null_Result(rc, e);
}


static z_t4341_t z_io_rename(
    z_t82_t from, z_t82_t to
) {
    char* from_cstr = z_sv_to_cstr(from);
    char* to_cstr = z_sv_to_cstr(to);
    int rc = rename(from_cstr, to_cstr);
    int e = errno;
    free(from_cstr);
    free(to_cstr);
    return z_io_wrap_null_Result(rc, e);
}


